def transform(grid):
    from collections import Counter
    g=[row[:] for row in grid]
    special=min(Counter(x for row in grid for x in row), key=lambda x: list(x for row in grid for x in row).count(x))
    marked=set()
    for br in range(7):
        for bc in range(7):
            tile=[row[1+4*bc:4+4*bc] for row in grid[1+4*br:4+4*br]]
            if any(special in row for row in tile): marked.add((br,bc))
    if not marked: return g
    br,bc=next(iter(marked))
    pattern=[row[1+4*bc:4+4*bc] for row in grid[1+4*br:4+4*br]]
    rs=[r for r,c in marked]; cs=[c for r,c in marked]
    height=max(rs)-min(rs)+1; width=max(cs)-min(cs)+1
    r0=max(1,min(rs)-(3-height)); c0=max(1,min(cs)-(3-width))
    target={(r,c) for r in range(r0,r0+3) for c in range(c0,c0+3)}
    if height==2:
        target={(r0,c0+1)}|{(r,c) for r in (r0+1,r0+2) for c in range(c0,c0+3)}
    for r,c in target:
        for dr in range(3):
            for dc in range(3): g[1+4*r+dr][1+4*c+dc]=pattern[dr][dc]
    return g

